"use client";
import * as Sentry from "@sentry/nextjs";
import Image from "next/image";
import { useState, useEffect, useRef } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import Pagination from "../pagination/pagination";
import getAttractions from "@/services/attractionsPageService";
import AttractionsListSkeleton from "./list-skeleton";

type Attraction = {
  id: number;
  name: string;
  slug: string;
  media: { thumb?: string; main?: string; high?: string }[];
  type: string;
  short_description?: string;
  description?: string;
};

// Strip HTML tags / entities for use as a plain-text excerpt.
const toExcerpt = (html?: string): string => {
  if (!html) return "";
  return html
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&#39;|&rsquo;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, " ")
    .trim();
};

const attractionImage = (item: Attraction): string =>
  item.media?.[0]?.high ||
  item.media?.[0]?.main ||
  item.media?.[0]?.thumb ||
  "/images/img-placeholder.png";

export default function Page({ attractionsData }: { attractionsData: any }) {
  const [attractions, setAttractions] = useState<Attraction[]>(
    attractionsData.data || []
  );
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const totalAttractions = attractionsData.meta.total || 0;
  const itemsPerPage = attractionsData.meta.per_page || 9; // backend page size

  const pageCacheRef = useRef<{ [key: number]: Attraction[] }>({
    1: attractionsData.data || [],
  });
  const topRef = useRef<HTMLDivElement>(null);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    topRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  useEffect(() => {
    if (pageCacheRef.current[currentPage]) {
      setAttractions(pageCacheRef.current[currentPage]);
      return;
    }
    const fetchPage = async () => {
      setLoading(true);
      try {
        const result = await getAttractions({ page: currentPage });
        pageCacheRef.current[currentPage] = result.data || [];
        setAttractions(result.data || []);
      } catch (error) {
        Sentry.captureException(error);
      } finally {
        setLoading(false);
      }
    };
    fetchPage();
  }, [currentPage]);

  const currentItems = attractions;

  return (
    <main>
      <div ref={topRef} className="tw-scroll-mt-4" />
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-4 tw-font-display">
        <Breadcrumb
          items={[{ pageTitle: "Attractions", pageUrl: "/attractions" }]}
        />

        <h1 className="tw-text-[24px] tw-font-bold tw-text-[#14101c] tw-mb-2">
          Top Tourist Attractions &amp; Best Things to Do
        </h1>
        <p className="tw-text-[15px] tw-leading-relaxed tw-text-[#5d556c] tw-m-0">
          From ancient ruins to hidden gulfs, discover the places worth
          travelling for &mdash; and start planning your next unforgettable trip.
        </p>
      </div>

      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4">
        {loading && <AttractionsListSkeleton />}
      </div>
      {!loading && (
        <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-font-display">
          {currentItems.length > 0 ? (
            <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 tw-mt-8">
              {currentItems.map((item: Attraction) => {
                const excerpt =
                  toExcerpt(item.short_description) || toExcerpt(item.description);
                return (
                  <a
                    href={"/attractions/" + item.slug}
                    target="_blank"
                    title={item.name}
                    key={item.id}
                    className="tw-group tw-flex tw-flex-col tw-h-full tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-overflow-hidden tw-no-underline tw-transition-all tw-duration-300 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)] hover:tw--translate-y-1"
                  >
                    <div className="tw-relative tw-overflow-hidden tw-rounded-t-2xl tw-transform-gpu">
                      <div className="tw-aspect-[4/3] tw-w-full tw-bg-[#f3f1f7]">
                        <Image
                          src={attractionImage(item)}
                          alt={item.name}
                          width={600}
                          height={450}
                          className="tw-w-full tw-h-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
                          loading="lazy"
                          quality={90}
                          sizes="(max-width: 768px) 50vw, (max-width: 1024px) 33vw, 25vw"
                        />
                      </div>
                      {item.type && (
                        <span className="tw-absolute tw-top-3 tw-left-3 tw-rounded-full tw-bg-white/95 tw-backdrop-blur tw-text-[#854ec9] tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-wide tw-px-2.5 tw-py-1 tw-shadow-sm">
                          {item.type}
                        </span>
                      )}
                    </div>
                    <div className="tw-flex tw-flex-col tw-flex-grow tw-p-4">
                      <h3 className="tw-text-[16px] tw-font-bold tw-leading-snug tw-text-[#14101c] tw-mb-1.5 tw-line-clamp-1 group-hover:tw-text-[#854ec9] tw-transition-colors">
                        {item.name}
                      </h3>
                      {excerpt && (
                        <p className="tw-text-[13.5px] tw-leading-relaxed tw-text-[#5d556c] tw-m-0 tw-line-clamp-3">
                          {excerpt}
                        </p>
                      )}
                      <span className="tw-mt-auto tw-pt-3 tw-inline-flex tw-items-center tw-gap-1 tw-text-[13px] tw-font-semibold tw-text-[#854ec9]">
                        Explore
                        <span aria-hidden="true" className="tw-transition-transform group-hover:tw-translate-x-0.5">→</span>
                      </span>
                    </div>
                  </a>
                );
              })}
            </div>
          ) : (
            <div className="tw-text-center tw-my-12">
              <p className="tw-text-[#5d556c]">No attractions found.</p>
            </div>
          )}
          {attractions.length > 0 && (
            <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 sm:tw-flex-row sm:tw-justify-between tw-mt-4">
              <p className="tw-text-[#5d556c] tw-text-[13px] tw-m-0">
                Showing {(currentPage - 1) * itemsPerPage + 1}-
                {Math.min(currentPage * itemsPerPage, totalAttractions)} of{" "}
                {totalAttractions} attraction
                {totalAttractions !== 1 ? "s" : ""}
              </p>
              <Pagination
                currentPage={currentPage}
                totalCount={totalAttractions}
                pageSize={itemsPerPage}
                onPageChange={handlePageChange}
              />
            </div>
          )}
        </div>
      )}

      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-mt-14 tw-mb-16 tw-font-display tw-text-[#5d556c] tw-text-[14px] tw-leading-relaxed [&_p]:tw-mb-4">
        <h2 className="tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-mb-3">
          About Attractions on TravelShop Booking
        </h2>
        <p>
          The attractions tab organizes the most important information into
          categories to facilitate and shorten all searching, reading and
          exploring processes that might be confusing and time waste.
        </p>
        <p>
          It separates and lists the well-known and unknown destinations
          location-based such as historical ruins, monuments, ancient
          temples, zoos, entertainment facilities, art galleries, botanical
          gardens, indoor and outdoor activities, and else smartly.
        </p>
        <p>
          This category will help you gather more precise, current, and reliable
          information about the attractions on your destination, so you
          don&rsquo;t get lost in search bars, pages of search results, blogs,
          or the web... You may quickly discover the attraction that you are
          seeking in this session because it has been classed as a list that is
          grouped under the city names.
        </p>
        <p>
          When you go to that web page, you&rsquo;ll get a concise,
          well-designed piece of pure information with good shots. This will
          assist you while deciding about where you will go, what you will see,
          and why you need to choose it or go?
        </p>
        <p>
          So, while you plan your next amazing trip, this session will help you
          find new places to visit as well as provide suggestions or inspiration
          for new, never thought or hear before destinations.
        </p>
      </div>
    </main>
  );
}
